{
  "technical_and_design_decisions": [
    "U1: Use Spring Batch's execution context to aggregate progress from child jobs; expose via REST endpoint; frontend polls for updates.",
    "U2: Reuse existing Spring Batch restart mechanism; allow restart of composed job as a whole, optionally from last failed step.",
    "U3: Create a dedicated compatibility test module comparing Kafka 0.9 API changes with the current version; produce a report and prototype.",
    "U4: Dockerize Lattice components for local testing; document bootstrap steps and configuration options for bare-metal deployment.",
    "U5: Implement a custom PropertySource that splits dot-delimited keys into nested map structures for Tuple and JSON property resolution.",
    "U6: Use JLine 3 for tab completion; integrate with Spring Shell command definitions to provide module and option suggestions.",
    "U7: Implement a Mesos deployer using Marathon for job scheduling; create a new deployer module following existing pattern.",
    "U8: Extract Redis @Rule test fixture into a separate Maven module/repo; update parent project dependencies and CI configuration."
  ],
  "assumptions": [
    "Developer is familiar with Spring Framework, Spring Cloud Data Flow, and Spring Cloud Stream codebases.",
    "All user stories are implemented in a single increment and are independent (no conflicting changes).",
    "Existing CI/CD pipeline and build infrastructure are already in place; no need for new tooling.",
    "Effort includes unit and integration testing, as well as documentation updates for each feature.",
    "Investigation stories (U3, U4) produce a written report and a minimal prototype/proof-of-concept.",
    "Effort estimates are in work-hours and represent the most likely time required for a single developer.",
    "No external dependencies or third-party approvals are needed beyond standard open-source collaboration."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Implement aggregated progress bar for composed job (U1)",
      "activity_description": "Develop backend logic to aggregate progress from multiple child jobs within a composed job, expose via REST API, and update frontend to display a progress bar.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A2",
      "activity_name": "Implement restart support for composed job (U2)",
      "activity_description": "Add ability to restart an existing composed job, including handling of child job states, REST endpoint changes, and UI button for restart.",
      "most_likely_effort": 30
    },
    {
      "activity_id": "A3",
      "activity_name": "Investigate Kafka 0.9 integration options (U3)",
      "activity_description": "Research API changes in Kafka 0.9, create compatibility test module, and produce a report outlining areas of improvement and integration feasibility.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A4",
      "activity_name": "Explore Lattice infrastructure bootstrapping (U4)",
      "activity_description": "Research Lattice (container orchestration) setup for bare-metal deployment of Spring Cloud Data Flow; create Docker-based local environment and document steps.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A5",
      "activity_name": "Implement dot-delimited property resolution (U5)",
      "activity_description": "Extend property resolution in Spring Cloud Stream to support dot-delimited syntax for Tuple and JSON, allowing nested property access in stream definitions.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A6",
      "activity_name": "Implement tab completion in shell (U6)",
      "activity_description": "Add tab completion functionality to the Spring Cloud Data Flow shell using JLine, enabling autocomplete for modules and options.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A7",
      "activity_name": "Implement Mesos deployment support (U7)",
      "activity_description": "Develop a new deployer for Apache Mesos (using Marathon) for Spring Cloud Data Flow; include scheduler integration, configuration, and testing.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A8",
      "activity_name": "Move Redis @Rule to separate repo (U8)",
      "activity_description": "Extract the Redis @Rule test fixture from the main repository into its own Maven module/repo, update dependencies, and set up CI.",
      "most_likely_effort": 12
    }
  ],
  "reported_total": {
    "most_likely_effort": 202
  }
}

